def _retry_wait(r: Response, now: Callable[[], datetime]) -> float:
    default = 2 if r.status == 503 else 1
    val = None
    for k, v in r.headers.items():
        if k.lower() == "retry-after":
            val = v.strip()
    if not val:
        return default
    if val.isdigit():
        return int(val)
    try:
